using System.Net.Http.Headers;using System.Text.Json;
namespace Satusehat.IntegrationSdk;
internal sealed class TokenProvider(SatusehatConfig c,HttpClient http){string? token;DateTimeOffset expires=DateTimeOffset.MinValue;readonly SemaphoreSlim gate=new(1,1);public void Invalidate(){token=null;expires=DateTimeOffset.MinValue;}public async Task<string> GetAsync(CancellationToken ct){await gate.WaitAsync(ct);try{if(token!=null&&DateTimeOffset.UtcNow<expires.AddSeconds(-60))return token;using var body=new FormUrlEncodedContent(new Dictionary<string,string>{{"client_id",c.ClientId},{"client_secret",c.ClientSecret}});using var req=new HttpRequestMessage(HttpMethod.Post,$"{c.OAuthBaseUrl}/accesstoken?grant_type=client_credentials") {Content=body};req.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));using var r=await http.SendAsync(req,ct);var text=await r.Content.ReadAsStringAsync(ct);if(!r.IsSuccessStatusCode)throw new InvalidOperationException($"OAuth HTTP {(int)r.StatusCode}: {text[..Math.Min(1000,text.Length)]}");using var doc=JsonDocument.Parse(text);if(!doc.RootElement.TryGetProperty("access_token",out var t))throw new InvalidOperationException("OAuth response missing access_token");token=t.GetString()??throw new InvalidOperationException("empty access_token");var sec=300;if(doc.RootElement.TryGetProperty("expires_in",out var e)){if(e.ValueKind==JsonValueKind.String){if(int.TryParse(e.GetString(),out var parsed))sec=parsed;}else if(e.TryGetInt32(out var n))sec=n;}expires=DateTimeOffset.UtcNow.AddSeconds(sec);return token;}finally{gate.Release();}}}
